mkdir -p migrations/down && cat > migrations/002_login_attempts.sql <<'EOF'
-- Shared counters for rate limiting (login). One row per key; the window restarts when `since` is old.
create table login_attempts (
  key text primary key,
  n integer not null check (n >= 0),
  since timestamptz not null default now()
);
EOF
cat > migrations/down/002_login_attempts.sql <<'EOF'
drop table login_attempts;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('''import { pool } from "./db.ts";
''','''import { pool } from "./db.ts";
import { hashPassword, verifyPassword } from "./passwords.ts";
''')
s=s.replace('''export function createApp''','''const LOGIN_WINDOW = "15 minutes";
const LOGIN_MAX_PER_EMAIL = 10;
const LOGIN_MAX_PER_IP = 50;
const MAX_PASSWORD_LENGTH = 1024;

// Counts a try atomically (before any check) in the database, so parallel guesses can't slip under the limit.
async function countAttempt(key: string): Promise<number> {
  const { rows } = await pool.query(
    `insert into login_attempts (key, n, since) values ($1, 1, now())
     on conflict (key) do update set
       n = case when login_attempts.since < now() - $2::interval then 1 else login_attempts.n + 1 end,
       since = case when login_attempts.since < now() - $2::interval then now() else login_attempts.since end
     returning n`,
    [key, LOGIN_WINDOW],
  );
  return rows[0].n;
}

// Used to spend the same time on unknown emails as on wrong passwords.
const dummyHash = hashPassword("dummy-password");

export function createApp''')
s=s.replace('''  app.use(auth);
''','''  app.post("/login", async (req, res) => {
    const { email, password } = req.body ?? {};
    if (typeof email !== "string" || typeof password !== "string" || email === "" || password === "") {
      return sendError(res, 400, "invalid_request", "email and password are required strings");
    }
    if (password.length > MAX_PASSWORD_LENGTH || email.length > 320) {
      return sendError(res, 400, "invalid_request", "email or password is too long");
    }

    const byEmail = await countAttempt(`login:${email.toLowerCase()}`);
    const byIp = await countAttempt(`login-ip:${req.ip ?? "unknown"}`);
    if (byEmail > LOGIN_MAX_PER_EMAIL || byIp > LOGIN_MAX_PER_IP) {
      return sendError(res, 429, "too_many_attempts", "Too many attempts, try again later");
    }

    const { rows } = await pool.query("select api_token, password_hash from users where email = $1", [email]);
    let ok = false;
    try {
      ok = await verifyPassword(password, rows[0]?.password_hash ?? (await dummyHash));
    } catch {
      ok = false;
    }
    if (!ok || rows.length === 0) {
      return sendError(res, 401, "invalid_credentials", "Invalid email or password");
    }
    res.json({ token: rows[0].api_token });
  });

  app.use(auth);
''')
open(p,'w').write(s)

p='postman/shop-api.postman_collection.json'
